#!/usr/bin/env bash
set -e

# Environment
BASEPATH="$(pwd)"
OUTPUTS="$BASEPATH/outputs"
mkdir -p "$OUTPUTS"

# SDL
ARGS=( cmake .. -G "Ninja" -DSDL_SHARED=OFF -DSDL_STATIC=ON -DCMAKE_SYSTEM_NAME=iOS -DCMAKE_OSX_SYSROOT=$EXTRA -DCMAKE_OSX_ARCHITECTURES=$CPU -DCMAKE_OSX_DEPLOYMENT_TARGET=13.0 )
source "$BASEPATH/.github/scripts/Libraries/SDL.sh"
cp "$INSTALLPATH/lib/libSDL3.a" "$OUTPUTS"

# SDL_image
ARGS=( cmake .. -G "Ninja" -DBUILD_SHARED_LIBS=OFF -DCMAKE_SYSTEM_NAME=iOS -DCMAKE_OSX_SYSROOT=$EXTRA -DCMAKE_OSX_ARCHITECTURES=$CPU -DCMAKE_OSX_DEPLOYMENT_TARGET=13.0 -DSDL3_DIR="$BASEPATH/SDL/install_output/lib/cmake/SDL3" )
source "$BASEPATH/.github/scripts/Libraries/SDL_image.sh"
cp "$INSTALLPATH/lib/libSDL3_image.a" "$OUTPUTS"

# SDL_mixer
ARGS=( cmake .. -G "Ninja" -DBUILD_SHARED_LIBS=OFF -DCMAKE_SYSTEM_NAME=iOS -DCMAKE_OSX_SYSROOT=$EXTRA -DCMAKE_OSX_ARCHITECTURES=$CPU -DCMAKE_OSX_DEPLOYMENT_TARGET=13.0 -DSDL3_DIR="$BASEPATH/SDL/install_output/lib/cmake/SDL3" )
source "$BASEPATH/.github/scripts/Libraries/SDL_mixer.sh"
cp "$INSTALLPATH/lib/libSDL3_mixer.a" "$OUTPUTS"

# SDL_ttf
ARGS=( cmake .. -G "Ninja" -DBUILD_SHARED_LIBS=OFF -DCMAKE_SYSTEM_NAME=iOS -DCMAKE_OSX_SYSROOT=$EXTRA -DCMAKE_OSX_ARCHITECTURES=$CPU -DCMAKE_OSX_DEPLOYMENT_TARGET=13.0 -DSDL3_DIR="$BASEPATH/SDL/install_output/lib/cmake/SDL3" )
source "$BASEPATH/.github/scripts/Libraries/SDL_ttf.sh"
cp "$INSTALLPATH/lib/libSDL3_ttf.a" "$OUTPUTS"